 "content": "from collections import deque


def _connected_nonzero(panel):
    cells = {(r, c) for r, row in enumerate(panel) for c, value in enumerate(row) if value != 0}
    if not cells:
        return False
    seen = {next(iter(cells))}
    q = deque(seen)
    while q:
        r, c = q.popleft()
        for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if p in cells and p not in seen:
                seen.add(p)
                q.append(p)
    return seen == cells


def transform(grid):
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]
    if _connected_nonzero(right):
        return [[left[r][c] if left[r][c] != 0 else right[r][c]
                 for c in range(4)] for r in range(4)]
    return left
